add_filter( 'manage_users_columns', 'perfectpixel_users_table_columns' );
add_filter( 'manage_users_custom_column', 'perfectpixel_users_table_column_value', 10, 3 );

function perfectpixel_users_table_columns( $columns ) {
	if ( '' !== sanitize_key( '{{users_column_meta_key}}' ) ) {
		$columns['perfectpixel_meta'] = '{{users_column_meta_label}}';
	}
	$columns['perfectpixel_orders'] = 'Παραγγελίες';
	$columns['perfectpixel_spent']  = 'Σύνολο αγορών';
	return $columns;
}

function perfectpixel_users_table_column_value( $output, $column, $user_id ) {
	switch ( $column ) {
		case 'perfectpixel_meta':
			return esc_html( (string) get_user_meta( $user_id, sanitize_key( '{{users_column_meta_key}}' ), true ) );
		case 'perfectpixel_orders':
			return esc_html( wc_get_customer_order_count( $user_id ) );
		case 'perfectpixel_spent':
			return wp_kses_post( wc_price( wc_get_customer_total_spent( $user_id ) ) );
	}
	return $output;
}
